definitions={'gdn_prefill':'gdn_prefill_qk4_v8_d128_k_last','dsa_attention':'dsa_sparse_attention_h16_ckv512_kpe64_topk2048_ps64','moe':'moe_fp8_block_scale_ds_routing_topk8_ng8_kg4_e32_h7168_i2048'}
