definitions.update(gdn_decode='gdn_decode_qk4_v8_d128_k_last',mla_decode='mla_paged_decode_h16_ckv512_kpe64_ps1')
name=definitions[group]
_,workloads,_=official._definition(name)
selected=workloads[int(os.environ['BASELINE_SHARD'])::int(os.environ['BASELINE_SHARDS'])]
selected=[w for w in selected if any(w.uuid.startswith(p) for p in ['a9540651', '62447caf', '07aa7922'])]
assert len(selected)==3
expected=[w.uuid for w in selected]
(root/'expected.json').write_text(json.dumps(expected))
print('BASELINE_EXPECTED',group,len(workloads),expected,flush=True)
# Discover historical Top-k sources without traversing unrelated project trees.
for directory in ('expert-line-audit-c2264b2/reference','kernelgoal-remainder-03413a0/upstream/goal_single_shape/dsa_topk_indexer'):
 p=pathlib.Path('/jiuzhang_train/user/chenyaojian')/directory
 print('BASELINE_SOURCE_INVENTORY',str(p),[str(f) for f in p.rglob('*') if f.name in ('ref_entry.py','kernel.py')],flush=True)
exits=[]
for workload in selected:
 spec=dict(expert=group,definition=name,uuid=workload.uuid,dataset=str(official.DATA))
 env=dict(os.environ,BASELINE_SPEC=json.dumps(spec))
 log=root/(workload.uuid+'.log')
 with log.open('w') as f:
  try:code=subprocess.run([sys.executable,'-u','test_expert_baseline_gpu.py','-v'],env=env,stdout=f,stderr=subprocess.STDOUT,timeout=1200).returncode
